  actionLabel = "View update",
  onAction,
  onDismiss,
  className,
}: Alert05Props) {
  const [visible, setVisible] = useState(true);
  const [exiting, setExiting] = useState(false);

  const handleDismiss = () => {
    setExiting(true);

    setTimeout(() => {
