  daysRemaining?: number;
  amount?: string;
  renewalDate?: string;
  onUpgrade?: () => void;
  onManageBilling?: () => void;
  onDismiss?: () => void;
  className?: string;
}

export default function Alert18({
  planName = "Pro",
  daysRemaining = 3,
  amount = "$24",
  renewalDate = "Oct 4, 2026",
  onUpgrade,
  onManageBilling,
  onDismiss,
  className,
}: Alert18Props) {
  const [isVisible, setIsVisible] = useState(true);
  const [isExiting, setIsExiting] = useState(false);

  const isUrgent = daysRemaining <= 3;

  const handleDismiss = () => {
    setIsExiting(true);

    setTimeout(() => {
      setIsVisible(false);
      onDismiss?.();
    }, 200);
  };

  if (!isVisible) return null;

  return (
    <div
      className={cn(
        "w-full max-w-lg overflow-hidden rounded-2xl",
        "border",
        isUrgent ? "border-amber-400/15" : "border-white/[0.08]",
        "bg-[#0C0C0F] backdrop-blur-xl",
        "shadow-[0_20px_60px_rgba(0,0,0,0.4)]",
        "transition-all duration-200",
        isExiting && "translate-y-2 opacity-0",
        className,
      )}
    >
      {isUrgent && (
        <div className="border-b border-amber-400/10 bg-amber-400/[0.06] px-5 py-2.5">
          <p className="text-[11px] font-medium uppercase tracking-[0.1em] text-amber-400">
            Action required · Subscription expiring soon
          </p>
        </div>
      )}

      <div className="p-5">
        <div className="flex items-start gap-4">
          <div
            className={cn(
              "flex size-10 shrink-0 items-center justify-center rounded-xl border",
              isUrgent
                ? "border-amber-400/15 bg-amber-400/10"
                : "border-violet-400/15 bg-violet-400/10",
            )}
          >
            <CreditCard
              className={cn(
                "size-5",
                isUrgent ? "text-amber-400" : "text-violet-300",
              )}
            />
          </div>

          <div className="min-w-0 flex-1">
            <div className="flex items-start justify-between gap-3">
              <div>
                <h3 className="text-sm font-medium text-zinc-100">
                  {planName} plan
                </h3>

                <p className="mt-1 text-sm leading-5 text-zinc-500">
                  {daysRemaining} day{daysRemaining === 1 ? "" : "s"} remaining
                  before your subscription renews.
                </p>
              </div>

              <button
                onClick={handleDismiss}
                aria-label="Dismiss"
                className="flex size-7 shrink-0 items-center justify-center rounded-full text-zinc-600 transition hover:bg-white/[0.06] hover:text-zinc-300 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-400/40"
              >
                <X className="size-4" />
              </button>
            </div>

            <div className="mt-4 grid grid-cols-2 gap-3">
              <div className="rounded-xl border border-white/[0.06] bg-white/[0.025] p-3">
                <p className="text-[10px] uppercase tracking-[0.1em] text-zinc-600">
                  Next payment
                </p>
                <p className="mt-1 text-sm font-medium text-zinc-200">
                  {amount}
                  <span className="text-zinc-600"> / month</span>
                </p>
              </div>

              <div className="rounded-xl border border-white/[0.06] bg-white/[0.025] p-3">
                <p className="text-[10px] uppercase tracking-[0.1em] text-zinc-600">
                  Renewal
                </p>
                <p className="mt-1 text-sm font-medium text-zinc-200">
                  {renewalDate}
                </p>
              </div>
            </div>

            <p className="mt-3 text-xs text-zinc-600">
              Payment method <span className="text-zinc-400">•••• 4242</span>
            </p>
          </div>
        </div>

        <div className="mt-5 flex items-center justify-end gap-2 border-t border-white/[0.06] pt-4">
          <button
            onClick={onManageBilling}
            className="rounded-full border border-white/[0.08] bg-white/[0.025] px-4 py-2 text-xs font-medium text-zinc-400 transition hover:bg-white/[0.06] hover:text-zinc-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-400/40"
          >
            Manage billing
          </button>

          <button
            onClick={onUpgrade}
            className="rounded-full bg-white px-4 py-2 text-xs font-medium text-black transition hover:bg-zinc-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-400/50"
          >
            Upgrade plan
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  AlertCircle,
  Lock,
  ShieldCheck,
  Smartphone,
  X,
} from "lucide-react";
import { cn } from "@/lib/utils";

interface SecurityEvent {
  id: string;
  type: "login" | "device" | "password";
  title: string;
  description: string;
  time: string;
  icon: typeof Lock;
}

interface Alert19Props {
  title?: string;
  events?: SecurityEvent[];
  onReviewActivity?: () => void;
  onDismiss?: () => void;
  className?: string;
}

const defaultEvents: SecurityEvent[] = [
  {
    id: "1",
    type: "login",
    title: "New login detected",
    description: "A new login was detected from Chrome on Windows.",
    time: "2 minutes ago",
    icon: Lock,
  },
  {
    id: "2",
    type: "device",
    title: "New device added",
    description: "A Windows device was added to your account.",
    time: "1 hour ago",
    icon: Smartphone,
  },
  {
    id: "3",
    type: "password",
    title: "Password updated",
    description: "Your account password was recently changed.",
    time: "Yesterday",
    icon: Lock,
  },
];

export default function Alert19({
  title = "Security activity",
  events = defaultEvents,
  onReviewActivity,
  onDismiss,
  className,
}: Alert19Props) {
  const [isVisible, setIsVisible] = useState(true);
  const [isExiting, setIsExiting] = useState(false);

  const handleDismiss = () => {
    setIsExiting(true);

    setTimeout(() => {
      setIsVisible(false);
      onDismiss?.();
    }, 200);
  };

  if (!isVisible) return null;

  return (
    <div
      className={cn(
        "w-full max-w-lg overflow-hidden rounded-2xl",
        "border border-white/[0.08]",
        "bg-[#0C0C0F] backdrop-blur-xl",
        "shadow-[0_20px_60px_rgba(0,0,0,0.4)]",
        "transition-all duration-200",
        isExiting && "translate-y-2 opacity-0",
        className,
      )}
    >
      <div className="flex items-center gap-3 border-b border-white/[0.06] px-5 py-4">
        <div className="flex size-9 items-center justify-center rounded-xl border border-emerald-400/15 bg-emerald-400/10">
          <ShieldCheck className="size-4.5 text-emerald-400" />
        </div>

        <div className="flex-1">
          <h3 className="text-sm font-medium text-zinc-100">{title}</h3>
          <p className="mt-0.5 text-[11px] text-zinc-600">
            Review recent changes to your account.
          </p>
        </div>

        <button
          onClick={handleDismiss}
          aria-label="Dismiss"
          className="flex size-7 items-center justify-center rounded-full text-zinc-600 transition hover:bg-white/[0.06] hover:text-zinc-300 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-400/40"
        >
          <X className="size-4" />
        </button>
      </div>

      <div className="space-y-2 p-4">
        {events.map((event) => {
          const Icon = event.icon;

          return (
            <div
              key={event.id}
              className="flex gap-3 rounded-xl border border-white/[0.05] bg-white/[0.02] p-3.5"
            >
              <div className="flex size-8 shrink-0 items-center justify-center rounded-full bg-white/[0.04] text-zinc-400">
                <Icon className="size-4" />
              </div>

              <div className="min-w-0 flex-1">
                <p className="text-sm font-medium text-zinc-200">
                  {event.title}
                </p>

                <p className="mt-1 text-xs leading-5 text-zinc-600">
                  {event.description}
                </p>

                <p className="mt-1.5 text-[10px] uppercase tracking-[0.08em] text-zinc-700">
                  {event.time}
                </p>
              </div>
            </div>
          );
        })}
      </div>

      <div className="flex items-center justify-between gap-3 border-t border-white/[0.06] px-5 py-3">
        <button
          type="button"
          className="inline-flex items-center gap-1.5 text-xs text-red-400 transition hover:text-red-300 focus-visible:outline-none"
        >
          <AlertCircle className="size-3.5" />
          Wasn't you? Secure account
        </button>

        <button
          onClick={onReviewActivity}
          className="rounded-full bg-white px-4 py-2 text-xs font-medium text-black transition hover:bg-zinc-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-400/50"
        >
          Review activity
        </button>
      </div>
    </div>
  );
}

"use client";

import { useState, type FormEvent } from "react";
import {
  Check,
  Search,
  UserPlus,
  Users,
  X,
} from "lucide-react";
import { cn } from "@/lib/utils";

interface TeamMember {
  id: string;
  name: string;
  email: string;
  avatar: string;
  role: string;
  online: boolean;
}

interface Alert20Props {
  title?: string;
  description?: string;
  members?: TeamMember[];
  onInvite?: (email: string) => void;
  onDismiss?: () => void;
  className?: string;
}

const defaultMembers: TeamMember[] = [
  {
    id: "1",
    name: "Alex Morgan",
    email: "alex@example.com",
    avatar: "https://i.pravatar.cc/100?img=11",
    role: "Owner",
    online: true,
  },
  {
    id: "2",
    name: "Sarah Chen",
    email: "sarah@example.com",
    avatar: "https://i.pravatar.cc/100?img=47",
    role: "Editor",
    online: true,
  },
  {
    id: "3",
    name: "Mike Ross",
    email: "mike@example.com",
    avatar: "https://i.pravatar.cc/100?img=12",
    role: "Viewer",
    online: false,
  },
];

export default function Alert20({
  title = "Team members",
  description = "Invite people to collaborate in your workspace.",
  members = defaultMembers,
  onInvite,
  onDismiss,
  className,
}: Alert20Props) {
  const [isVisible, setIsVisible] = useState(true);
  const [isExiting, setIsExiting] = useState(false);
  const [email, setEmail] = useState("");
  const [isInviting, setIsInviting] = useState(false);
  const [inviteSent, setInviteSent] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  const filteredMembers = members.filter((member) => {
    const query = searchQuery.toLowerCase();

    return (
      member.name.toLowerCase().includes(query) ||
      member.email.toLowerCase().includes(query)
    );
  });

  const handleDismiss = () => {
    setIsExiting(true);

    setTimeout(() => {
      setIsVisible(false);
      onDismiss?.();
    }, 200);
  };

  const handleInvite = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    if (!email.trim() || isInviting) return;

    setIsInviting(true);

    setTimeout(() => {
      onInvite?.(email);
      setIsInviting(false);
      setInviteSent(true);

      setTimeout(() => {
        setInviteSent(false);
        setEmail("");
      }, 2000);
    }, 1000);
  };

  if (!isVisible) return null;

  return (
    <div
      className={cn(
        "w-full max-w-lg overflow-hidden rounded-2xl",
        "border border-white/[0.08]",
        "bg-[#0C0C0F] backdrop-blur-xl",
        "shadow-[0_24px_70px_rgba(0,0,0,0.5)]",
        "transition-all duration-200",
        isExiting && "translate-y-2 opacity-0",
        className,
      )}
    >
      <div className="flex items-start gap-4 border-b border-white/[0.06] p-5">
        <div className="flex size-10 shrink-0 items-center justify-center rounded-xl border border-violet-400/15 bg-violet-400/10">
          <Users className="size-5 text-violet-300" />
        </div>

        <div className="min-w-0 flex-1">
          <div className="flex items-start justify-between gap-3">
            <div>
              <h3 className="text-sm font-medium text-zinc-100">{title}</h3>
              <p className="mt-1 text-xs leading-5 text-zinc-500">
                {description}
              </p>
            </div>

            <button
              onClick={handleDismiss}
              aria-label="Dismiss"
              className="flex size-7 shrink-0 items-center justify-center rounded-full text-zinc-600 transition hover:bg-white/[0.06] hover:text-zinc-300 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-400/40"
            >
              <X className="size-4" />
            </button>
          </div>
        </div>
      </div>

      <div className="p-5">
        <form onSubmit={handleInvite}>
          <div className="flex gap-2">
            <div className="relative min-w-0 flex-1">
              <UserPlus className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-zinc-600" />

              <input
                type="email"
                value={email}
                onChange={(event) => setEmail(event.target.value)}
                placeholder="name@example.com"
                className={cn(
                  "h-10 w-full rounded-xl border border-white/[0.08]",
                  "bg-white/[0.025] pl-9 pr-3",
                  "text-sm text-zinc-200 placeholder:text-zinc-700",
                  "transition-all duration-200",
                  "focus:border-violet-400/30 focus:bg-white/[0.04]",
                  "focus:outline-none focus:ring-2 focus:ring-violet-400/10",
                )}
              />
            </div>

            <button
              type="submit"
              disabled={isInviting || !email.trim()}
              className={cn(
                "inline-flex h-10 shrink-0 items-center gap-2 rounded-full px-4",
                "text-xs font-medium",
                "transition-all duration-200",
                inviteSent
                  ? "bg-emerald-400/10 text-emerald-400"
                  : "bg-white text-black hover:bg-zinc-200",
                "disabled:cursor-not-allowed disabled:opacity-40",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-violet-400/50",
              )}
            >
              {inviteSent ? (
                <>
                  <Check className="size-3.5" />
                  Sent
                </>
              ) : (
                <>
                  <UserPlus className="size-3.5" />
                  {isInviting ? "Inviting..." : "Invite"}
                </>
              )}
            </button>
          </div>
        </form>

        <div className="relative mt-5">
          <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-zinc-600" />

          <input
            type="text"
            value={searchQuery}
            onChange={(event) => setSearchQuery(event.target.value)}
            placeholder="Search members..."
            className="h-9 w-full rounded-xl border border-white/[0.06] bg-white/[0.02] pl-9 pr-3 text-xs text-zinc-300 placeholder:text-zinc-700 transition focus:border-violet-400/30 focus:outline-none focus:ring-2 focus:ring-violet-400/10"
          />
        </div>

        <div className="mt-4 space-y-1">
          {filteredMembers.map((member) => (
            <div
              key={member.id}
              className="flex items-center gap-3 rounded-xl px-3 py-2.5 transition hover:bg-white/[0.025]"
            >
              <div className="relative shrink-0">
                <img
                  src={member.avatar}
                  alt={member.name}
                  className="size-8 rounded-full border border-white/[0.08] object-cover"
                />

                <span
                  className={cn(
                    "absolute -bottom-0.5 -right-0.5 size-2.5 rounded-full border-2 border-[#0C0C0F]",
                    member.online ? "bg-emerald-400" : "bg-zinc-700",
                  )}
                />
              </div>

              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-zinc-200">
                  {member.name}
                </p>
                <p className="truncate text-[11px] text-zinc-600">
                  {member.email}
                </p>
              </div>

              <span
                className={cn(
                  "rounded-full border px-2.5 py-1 text-[10px] font-medium",
                  member.role === "Owner"
                    ? "border-violet-400/15 bg-violet-400/10 text-violet-300"
                    : member.role === "Editor"
                      ? "border-white/[0.08] bg-white/[0.035] text-zinc-400"
                      : "border-white/[0.06] text-zinc-600",
                )}
              >
                {member.role}
              </span>
            </div>
          ))}

          {filteredMembers.length === 0 && (
            <div className="py-8 text-center">
              <p className="text-xs text-zinc-600">No members found.</p>
            </div>
          )}
        </div>
      </div>

      <div className="flex items-center justify-between border-t border-white/[0.06] px-5 py-3">
        <span className="text-[11px] text-zinc-600">
          {members.length} member{members.length === 1 ? "" : "s"}
        </span>

        <span className="text-[10px] uppercase tracking-[0.12em] text-zinc-700">
          Workspace
        </span>
      </div>
    </div>
  );
}
